    }

    /**
     * Sets the refresh buffer flag.  This flag is used to avoid unnecessary
     * redrawing of the chart when the offscreen image buffer is used.
     *
     * @param flag  <code>true</code> indicates that the buffer should be
     *              refreshed.
     */
    public void setRefreshBuffer(boolean flag) {
        this.refreshBuffer = flag;
    }

    /**
     * Paints the component by drawing the chart to fill the entire component,
     * but allowing for the insets (which will be non-zero if a border has been
     * set for this component).  To increase performance (at the expense of
     * memory), an off-screen buffer image can be used.
     *
     * @param g  the graphics device for drawing on.
     */
    @Override
    public void paintComponent(Graphics g) {
        super.paintComponent(g);
        if (this.chart == null) {
            return;
        }
        Graphics2D g2 = (Graphics2D) g.create();

        // compute scaling and chart area
        ScaleInfo scaleInfo = computeScale(getSize(), getInsets());

        // draw chart
        if (this.useBuffer) {
            drawChartWithBuffer(g2, scaleInfo);
        } else {
            drawChartWithoutBuffer(g2, scaleInfo);
        }

        // draw overlays
        drawOverlays(g2);

        // draw zoom rectangle
        drawZoomRectangle(g2, !this.useBuffer);

        g2.dispose();

        resetState();
    }

    /**
     * Computes scaling information for the current component size.
     *
     * @param size  the component size.
     * @param insets  the component insets.
     * @return a {@link ScaleInfo} instance.
     */
    private ScaleInfo computeScale(Dimension size, Insets insets) {
        double drawWidth = size.getWidth() - insets.left - insets.right;
        double drawHeight = size.getHeight() - insets.top - insets.bottom;
        double scaleX = 1.0;
        double scaleY = 1.0;
        boolean scale = false;

        if (drawWidth < this.minimumDrawWidth) {
            scaleX = drawWidth / this.minimumDrawWidth;
            drawWidth = this.minimumDrawWidth;
            scale = true;
        } else if (drawWidth > this.maximumDrawWidth) {
            scaleX = drawWidth / this.maximumDrawWidth;
            drawWidth = this.maximumDrawWidth;
            scale = true;
        }

        if (drawHeight < this.minimumDrawHeight) {
            scaleY = drawHeight / this.minimumDrawHeight;
            drawHeight = this.minimumDrawHeight;
            scale = true;
        } else if (drawHeight > this.maximumDrawHeight) {
            scaleY = drawHeight / this.maximumDrawHeight;
            drawHeight = this.maximumDrawHeight;
            scale = true;
        }

        Rectangle2D chartArea = new Rectangle2D.Double(0.0, 0.0, drawWidth,
                drawHeight);

        return new ScaleInfo(scaleX, scaleY, scale, chartArea);
    }

    /**
     * Draws the chart using an off-screen buffer.
     *
     * @param g2  the graphics context.
     * @param scaleInfo  scaling information.
     */
    private void drawChartWithBuffer(Graphics2D g2, ScaleInfo scaleInfo) {
        Insets insets = getInsets();
        int bufferWidth = (int) (getSize().getWidth() - insets.left - insets.right);
        int bufferHeight = (int) (getSize().getHeight() - insets.top - insets.bottom);

        // resize buffer if necessary
        if (this.chartBuffer == null
                || this.chartBufferWidth != bufferWidth
                || this.chartBufferHeight != bufferHeight) {
            this.chartBufferWidth = bufferWidth;
            this.chartBufferHeight = bufferHeight;
            GraphicsConfiguration gc = g2.getDeviceConfiguration();
            this.chartBuffer = gc.createCompatibleImage(
                    this.chartBufferWidth, this.chartBufferHeight,
                    Transparency.TRANSLUCENT);
            this.refreshBuffer = true;
        }

        // redraw buffer if needed
        if (this.refreshBuffer) {
            this.refreshBuffer = false;
            Rectangle2D bufferArea = new Rectangle2D.Double(
                    0, 0, this.chartBufferWidth, this.chartBufferHeight);

            Graphics2D bufferG2 = (Graphics2D) this.chartBuffer.getGraphics();
            Composite savedComposite = bufferG2.getComposite();
            bufferG2.setComposite(AlphaComposite.getInstance(
                    AlphaComposite.CLEAR, 0.0f));
            Rectangle r = new Rectangle(0, 0, this.chartBufferWidth,
                    this.chartBufferHeight);
            bufferG2.fill(r);
            bufferG2.setComposite(savedComposite);

            if (scaleInfo.scale) {
                AffineTransform saved = bufferG2.getTransform();
                AffineTransform st = AffineTransform.getScaleInstance(
                        scaleInfo.scaleX, scaleInfo.scaleY);
                bufferG2.transform(st);
                this.chart.draw(bufferG2, scaleInfo.chartArea, this.anchor,
                        this.info);
                bufferG2.setTransform(saved);
            } else {
                this.chart.draw(bufferG2, bufferArea, this.anchor,
                        this.info);
            }
        }

        g2.drawImage(this.chartBuffer, insets.left, insets.top, this);
    }

    /**
     * Draws the chart directly onto the component.
     *
     * @param g2  the graphics context.
     * @param scaleInfo  scaling information.
     */
    private void drawChartWithoutBuffer(Graphics2D g2, ScaleInfo scaleInfo) {
        Insets insets = getInsets();
        AffineTransform saved = g2.getTransform();
        g2.translate(insets.left, insets.top);
        if (scaleInfo.scale) {
            AffineTransform st = AffineTransform.getScaleInstance(
                    scaleInfo.scaleX, scaleInfo.scaleY);
            g2.transform(st);
        }
        this.chart.draw(g2, scaleInfo.chartArea, this.anchor, this.info);
        g2.setTransform(saved);
    }

    /**
     * Draws all overlays on the panel.
     *
     * @param g2  the graphics context.
     */
    private void drawOverlays(Graphics2D g2) {
        Iterator iterator = this.overlays.iterator();
        while (iterator.hasNext()) {
            Overlay overlay = (Overlay) iterator.next();
            overlay.paintOverlay(g2, this);
        }
    }

    /**
     * Resets transient state after painting.
     */
    private void resetState() {
        this.anchor = null;
        this.verticalTraceLine = null;
        this.horizontalTraceLine = null;
    }

