    /**
     * Copy constructor used by the clone() method.
     *
     * @param source the source plot to copy.
     * @throws CloneNotSupportedException if cloning fails.
     */
    private PolarPlot(PolarPlot source) throws CloneNotSupportedException {
        try {
            // shallow clone of all fields, including those from Plot
            PolarPlot clone = (PolarPlot) Object.class.getDeclaredMethod("clone")
                    .invoke(source);
            copyFields(clone, this);

            // clone axes list and individual axes
            this.axes = (ObjectList) ObjectUtilities.clone(source.axes);
            for (int i = 0; i < this.axes.size(); i++) {
                ValueAxis axis = (ValueAxis) this.axes.get(i);
                if (axis != null) {
                    ValueAxis clonedAxis = (ValueAxis) axis.clone();
                    this.axes.set(i, clonedAxis);
                    clonedAxis.setPlot(this);
                    clonedAxis.addChangeListener(this);
                }
            }

            // clone datasets list and add listeners
            this.datasets = (ObjectList) ObjectUtilities.clone(source.datasets);
            for (int i = 0; i < this.datasets.size(); i++) {
                XYDataset d = source.getDataset(i);
                if (d != null) {
                    d.addChangeListener(this);
                }
            }

            // clone renderers list and clone renderers if possible
            this.renderers = (ObjectList) ObjectUtilities.clone(source.renderers);
            for (int i = 0; i < this.renderers.size(); i++) {
                PolarItemRenderer renderer2 = (PolarItemRenderer) this.renderers.get(i);
                if (renderer2 instanceof PublicCloneable) {
                    PublicCloneable pc = (PublicCloneable) renderer2;
                    PolarItemRenderer rc = (PolarItemRenderer) pc.clone();
                    this.renderers.set(i, rc);
                    rc.setPlot(this);
                    rc.addChangeListener(this);
                }
            }

            // clone corner text items
            this.cornerTextItems = new ArrayList(source.cornerTextItems);

            // clone dataset to axes map
            this.datasetToAxesMap = new TreeMap();
            for (Object key : source.datasetToAxesMap.keySet()) {
                List list = (List) source.datasetToAxesMap.get(key);
                this.datasetToAxesMap.put(key, new ArrayList(list));
            }

            // clone axis locations
            this.axisLocations = (ObjectList) ObjectUtilities.clone(source.axisLocations);
        } catch (Exception e) {
            throw new CloneNotSupportedException(e.getMessage());
        }
    }

    /**
     * Copies all non-static fields from the source object to the target object.
     *
     * @param src the source object.
     * @param dst the target object.
     * @throws IllegalAccessException if a field cannot be accessed.
     */
    private static void copyFields(Object src, Object dst) throws IllegalAccessException {
        Class<?> clazz = src.getClass();
        while (clazz != null) {
            for (Field f : clazz.getDeclaredFields()) {
                if (Modifier.isStatic(f.getModifiers())) {
                    continue;
                }
                f.setAccessible(true);
                f.set(dst, f.get(src));
            }
            clazz = clazz.getSuperclass();
        }
    }
}

