    /**
     * Constructor.
     * @param loggerName The name of the Logger.
     * @param marker The Marker or null.
     * @param loggerFQCN The fully qualified class name of the caller.
     * @param level The logging Level.
     * @param message The Message.
     * @param thrown A Throwable or null.
     * @param thrownProxy A ThrowableProxy or null.
     * @param contextMap The mapped diagnostic context.
     * @param contextStack the nested diagnostic context.
     * @param threadName The name of the thread.
     * @param source The locations of the caller.
     * @param timestamp The timestamp of the event.
     * @param nanoTime The value of the running Java Virtual Machine's high-resolution time source when the event was
     *          created.
     */
    private Log4jLogEvent(final LogEventParameters params, final long nanoTime) {
        this.loggerName = params.loggerName;
        this.marker = params.marker;
        this.loggerFqcn = params.loggerFqcn;
        this.level = params.level == null ? Level.OFF : params.level;
        this.message = params.message;
        this.thrown = params.thrown;
        this.thrownProxy = params.thrownProxy;
        this.contextMap = params.contextMap == null ? ThreadContext.EMPTY_MAP : params.contextMap;
        this.contextStack = params.contextStack == null ? ThreadContext.EMPTY_STACK : params.contextStack;
        this.timeMillis = params.message instanceof TimestampMessage ?
                ((TimestampMessage) params.message).getTimestamp() : params.timestampMillis;
        this.threadName = params.threadName;
        this.source = params.source;
        if (params.message != null && params.message instanceof LoggerNameAwareMessage) {
            ((LoggerNameAwareMessage) params.message).setLoggerName(params.loggerName);
        }
        this.nanoTime = nanoTime;
    }

    private static Map<String, String> createMap(final List<Property> properties) {
        final Map<String, String> contextMap = ThreadContext.getImmutableContext();
        if (properties == null || properties.isEmpty()) {
            return contextMap; // may be ThreadContext.EMPTY_MAP but not null
        }
        final Map<String, String> map = new HashMap<>(contextMap);

        for (final Property prop : properties) {
            if (!map.containsKey(prop.getName())) {
                map.put(prop.getName(), prop.getValue());
            }
        }
        return Collections.unmodifiableMap(map);
    }

