    static {
        Map<Class<?>, Function<Object, String>> map = new HashMap<>();
        map.put(byte[].class, o -> Arrays.toString((byte[]) o));
        map.put(short[].class, o -> Arrays.toString((short[]) o));
        map.put(int[].class, o -> Arrays.toString((int[]) o));
        map.put(long[].class, o -> Arrays.toString((long[]) o));
        map.put(float[].class, o -> Arrays.toString((float[]) o));
        map.put(double[].class, o -> Arrays.toString((double[]) o));
        map.put(boolean[].class, o -> Arrays.toString((boolean[]) o));
