        ARRAY_HANDLERS.put(long[].class, (o, str, d) -> str.append(Arrays.toString((long[]) o)));
        ARRAY_HANDLERS.put(float[].class, (o, str, d) -> str.append(Arrays.toString((float[]) o)));
        ARRAY_HANDLERS.put(double[].class, (o, str, d) -> str.append(Arrays.toString((double[]) o)));
