    }

    public String replace(final Object source) {
        return replace(null, source);
    }

    public String replace(final LogEvent event, final Object source) {
        if (source == null) {
            return null;
        }
        final StringBuilder buf = new StringBuilder().append(source);
        substitute(event, buf, 0, buf.length());
        return buf.toString();
    }

    protected boolean substitute(final LogEvent event, final StringBuilder buf, final int offset, final int length) {
        return substitute(event, buf, offset, length, null) > 0;
    }

    private int substitute(final LogEvent event, final StringBuilder buf, final int offset, final int length,
                           List<String> priorVariables) {
        final StrMatcher prefixMatcher = getVariablePrefixMatcher();
        final StrMatcher suffixMatcher = getVariableSuffixMatcher();
        final char escape = getEscapeChar();
        final StrMatcher valueDelimiterMatcher = getValueDelimiterMatcher();
        final boolean substitutionInVariablesEnabled = isEnableSubstitutionInVariables();

        final boolean top = priorVariables == null;
        boolean altered = false;
        int lengthChange = 0;
        char[] chars = getChars(buf);
        int bufEnd = offset + length;
        int pos = offset;
        while (pos < bufEnd) {
            int startMatchLen = prefixMatcher.isMatch(chars, pos, offset, bufEnd);
            if (startMatchLen == 0) {
                pos++;
                continue;
            }
            if (pos > offset && chars[pos - 1] == escape) {
                buf.deleteCharAt(pos - 1);
                chars = getChars(buf);
                lengthChange--;
                altered = true;
                bufEnd--;
                continue;
            }
            int startPos = pos;
            pos += startMatchLen;
            int endPos = findVariableEnd(chars, pos, bufEnd, prefixMatcher, suffixMatcher, substitutionInVariablesEnabled);
            String varNameExpr = new String(chars, startPos + startMatchLen, endPos - (startPos + startMatchLen));
            if (substitutionInVariablesEnabled) {
                StringBuilder bufName = new StringBuilder(varNameExpr);
                substitute(event, bufName, 0, bufName.length());
                varNameExpr = bufName.toString();
            }
            pos = endPos;
            String[] nameAndDefault = parseVariableNameAndDefault(varNameExpr, valueDelimiterMatcher,
                    substitutionInVariablesEnabled, prefixMatcher);
            String varName = nameAndDefault[0];
            String varDefaultValue = nameAndDefault[1];
            if (priorVariables == null) {
                priorVariables = new ArrayList<>();
                priorVariables.add(new String(chars, offset, length + lengthChange));
            }
            checkCyclicSubstitution(varName, priorVariables);
            priorVariables.add(varName);
            String varValue = resolveVariable(event, varName, buf, startPos, endPos);
            if (varValue == null) {
                varValue = varDefaultValue;
            }
            if (varValue != null) {
                int varLen = varValue.length();
                buf.replace(startPos, endPos, varValue);
                altered = true;
                int change = substitute(event, buf, startPos, varLen, priorVariables);
                change += varLen - (endPos - startPos);
                pos += change;
                bufEnd += change;
                lengthChange += change;
                chars = getChars(buf);
            }
            priorVariables.remove(priorVariables.size() - 1);
        }
        return top ? (altered ? 1 : 0) : lengthChange;
    }

    private int findVariableEnd(char[] chars, int pos, int bufEnd, StrMatcher prefixMatcher,
                                StrMatcher suffixMatcher, boolean substitutionInVariablesEnabled) {
        int nestedVarCount = 0;
        while (pos < bufEnd) {
            if (substitutionInVariablesEnabled) {
                int prefixLen = prefixMatcher.isMatch(chars, pos, pos, bufEnd);
                if (prefixLen != 0) {
                    nestedVarCount++;
                    pos += prefixLen;
                    continue;
                }
            }
            int suffixLen = suffixMatcher.isMatch(chars, pos, pos, bufEnd);
            if (suffixLen == 0) {
                pos++;
            } else {
                if (nestedVarCount == 0) {
                    pos += suffixLen;
                    break;
                } else {
                    nestedVarCount--;
                    pos += suffixLen;
                }
            }
        }
        return pos;
    }

    private String[] parseVariableNameAndDefault(String varNameExpr, StrMatcher valueDelimiterMatcher,
                                                 boolean substitutionInVariablesEnabled, StrMatcher prefixMatcher) {
        if (valueDelimiterMatcher == null) {
            return new String[]{varNameExpr, null};
        }
        char[] exprChars = varNameExpr.toCharArray();
        int delimiterLen = 0;
        for (int i = 0; i < exprChars.length; i++) {
            if (!substitutionInVariablesEnabled && prefixMatcher.isMatch(exprChars, i, i, exprChars.length) != 0) {
                break;
            }
            delimiterLen = valueDelimiterMatcher.isMatch(exprChars, i);
            if (delimiterLen != 0) {
                String varName = varNameExpr.substring(0, i);
                String defaultVal = varNameExpr.substring(i + delimiterLen);
                return new String[]{varName, defaultVal};
            }
        }
        return new String[]{varNameExpr, null};
    }

    private void checkCyclicSubstitution(final String varName, final List<String> priorVariables) {
        if (!priorVariables.contains(varName)) {
            return;
        }
        final StringBuilder buf = new StringBuilder(BUF_SIZE);
        buf.append("Infinite loop in property interpolation of ");
        buf.append(priorVariables.remove(0));
        buf.append(": ");
        appendWithSeparators(buf, priorVariables, "->");
        throw new IllegalStateException(buf.toString());
    }

    protected String resolveVariable(final LogEvent event, final String variableName, final StringBuilder buf,
                                     final int startPos, final int endPos) {
        final StrLookup resolver = getVariableResolver();
        if (resolver == null) {
            return null;
        }
        return resolver.lookup(event, variableName);
    }

    public char getEscapeChar() {
        return this.escapeChar;
    }

    public void setEscapeChar(final char escapeCharacter) {
